package com.colovision.controller;
import java.util.*; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.web.bind.annotation.*; import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> missing(Exception e){return error(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler({IllegalArgumentException.class,MethodArgumentTypeMismatchException.class}) ResponseEntity<?> invalid(Exception e){return error(HttpStatus.BAD_REQUEST,e.getMessage());} @ExceptionHandler(UnsupportedOperationException.class) ResponseEntity<?> type(Exception e){return error(HttpStatus.UNSUPPORTED_MEDIA_TYPE,e.getMessage());} @ExceptionHandler(BadCredentialsException.class) ResponseEntity<?> bad(Exception e){return error(HttpStatus.UNAUTHORIZED,e.getMessage());} @ExceptionHandler(AccessDeniedException.class) ResponseEntity<?> denied(Exception e){return error(HttpStatus.FORBIDDEN,e.getMessage());} @ExceptionHandler(IllegalStateException.class) ResponseEntity<?> unavailable(Exception e){return error(HttpStatus.SERVICE_UNAVAILABLE,e.getMessage());} private ResponseEntity<?> error(HttpStatus s,String m){return ResponseEntity.status(s).body(Map.of("detail",m==null?"Request could not be completed":m));} }
